// `admin` can do everything. `manager` manages the library and requests (as its permissions allow).
// `requester` only asks for titles.
// Ref: #/components/schemas/Role
type Role string

const (
	RoleAdmin     Role = "admin"
	RoleManager   Role = "manager"
	RoleRequester Role = "requester"
)

// AllValues returns all Role values.
func (Role) AllValues() []Role {
	return []Role{
		RoleAdmin,
		RoleManager,
		RoleRequester,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Role) MarshalText() ([]byte, error) {
	switch s {
	case RoleAdmin:
		return []byte(s), nil
	case RoleManager:
		return []byte(s), nil
	case RoleRequester:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Role) UnmarshalText(data []byte) error {
	switch Role(data) {
	case RoleAdmin:
		*s = RoleAdmin
		return nil
	case RoleManager:
		*s = RoleManager
		return nil
	case RoleRequester:
		*s = RoleRequester
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

